targets.expr:
count(
  {{operator_namespace}}controller_condition{job="$job", controller=~"$controller", condition="Ready", status="True"}
  and
  topk by (kind, id) (1, {{operator_namespace}}controller_condition{job="$job", controller=~"$controller", condition="Ready"})
)

count(
  {{operator_namespace}}controller_condition{job="$job", controller=~"$controller", condition="Ready", status="Unknown"}
  and
  topk by (kind, id) (1, {{operator_namespace}}controller_condition{job="$job", controller=~"$controller", condition="Ready"})
) or vector(0)

count by (condition, status) (
  {{operator_namespace}}controller_condition{job="$job", controller=~"$controller"}
  and
  topk by (kind, id, condition) (1, {{operator_namespace}}controller_condition{job="$job", controller=~"$controller"})
)

sum by (kind, {{namespace_label}}, name, reason, status, id) (
  {{operator_namespace}}controller_condition{job="$job", controller=~"$controller", condition="Ready", status!="True"}
  and
  topk by (kind, id) (1, {{operator_namespace}}controller_condition{job="$job", controller=~"$controller", condition="Ready"})
)
